use xiom.io;

enum Command {
  Move(distance: Int),
  Turn(degrees: Int),
  Speak(msg: Str),
  Wait(seconds: Int),
}

fn execute(cmd: Command) -> Str {
  match cmd {
    Move(dist) => { return "Moving forward " + dist + " steps"; }
    Turn(deg) => { return "Turning " + deg + " degrees"; }
    Speak(msg) => { return "Robot says: " + msg; }
    Wait(sec) => { return "Waiting " + sec + " seconds"; }
  }
}

fn main() -> Int {
  let c1 = Command.Move(10);
  let c2 = Command.Turn(90);
  let c3 = Command.Speak("Hello!");
  let c4 = Command.Wait(3);
  var total = 0;
  match c1 { Move(d) => { total = total + d; } _ => { } }
  match c4 { Wait(s) => { total = total + s; } _ => { } }
  return total;
}
